 public static void Run(){const string ev="Evidence/Target52Window";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget52Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);var from=new Vector3(15,20,21);var at=new Vector3(0,3.5f,0);
 var pixels=Shot(c,from,at,ev+"/room.png");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget52Output/Structures/Ruins.prefab"));Check(pixels.SequenceEqual(Shot(c,from,at,null)),"Prefab pixels");EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/RuinsTarget52Output/WindowPersistence.unity");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene("Assets/RuinsTarget52Output/WindowPersistence.unity");root=GameObject.Find("ruins_1").transform.parent.gameObject;c=UnityEngine.Object.FindAnyObjectByType<Camera>();sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);Check(pixels.SequenceEqual(Shot(c,from,at,null)),"Scene pixels");
 var old=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget51Output/Structures/Ruins.prefab"));int unchanged=0;foreach(Transform t in old.transform){if(!t.name.StartsWith("ruins_"))continue;var a=t.GetComponent<MeshFilter>().sharedMesh;var b=root.transform.Find(t.name).GetComponent<MeshFilter>().sharedMesh;Check(a.vertices.SequenceEqual(b.vertices)&&a.normals.SequenceEqual(b.normals)&&a.uv.SequenceEqual(b.uv)&&a.triangles.SequenceEqual(b.triangles),"Old geometry "+t.name);Check(root.transform.Find(t.name).GetComponent<MeshCollider>().sharedMesh==b,"Old Collider identity");unchanged++;}Check(unchanged==56,"Old fixture count");
 foreach(int id in new[]{57,58,59,60,61})root.transform.Find("ruins_"+id).gameObject.SetActive(false);root.SetActive(false);var before=Shot(c,from,at,null);old.SetActive(false);root.SetActive(true);Check(before.SequenceEqual(Shot(c,from,at,null)),"Existing pixels changed");UnityEngine.Object.DestroyImmediate(old);
 foreach(Transform t in root.transform)t.gameObject.SetActive(new[]{"ruins_57","ruins_58","ruins_59","ruins_60","ruins_61"}.Contains(t.name));c.orthographic=true;var centre=new Vector3(-8.5f,4.1f,-3);
 foreach(string view in new[]{"normal","close","opposite","rear"}){sun.transform.rotation=view=="opposite"?Quaternion.Euler(27,130,0):Quaternion.Euler(38,-28,0);c.orthographicSize=view=="normal"?4.7f:2.5f;Shot(c,centre+new Vector3(view=="rear"?-4:3,3.4f,view=="rear"?-7:7),centre,ev+"/windows-"+view+".png");}
 sun.transform.rotation=Quaternion.Euler(38,-28,0);foreach(int id in new[]{57,59,60,61})root.transform.Find("ruins_"+id).gameObject.SetActive(false);var obj=root.transform.Find("ruins_58").gameObject;var mr=obj.GetComponent<MeshRenderer>();var mf=obj.GetComponent<MeshFilter>();var saved=mf.sharedMesh;var mat=mr.sharedMaterial;c.orthographicSize=1.65f;centre=new Vector3(-7,4.1f,-3);Shot(c,centre+new Vector3(2.4f,2.4f,5),centre,ev+"/carved.png");mf.sharedMesh=root.transform.Find("ruins_57").GetComponent<MeshFilter>().sharedMesh;mr.sharedMaterial=root.transform.Find("ruins_57").GetComponent<MeshRenderer>().sharedMaterial;Shot(c,centre+new Vector3(2.4f,2.4f,5),centre,ev+"/plain.png");mf.sharedMesh=saved;mr.sharedMaterial=mat;
 foreach(Transform t in root.transform)t.gameObject.SetActive(true);Physics.SyncTransforms();int holes=0,solid=0;foreach(int id in new[]{57,58}){var col=root.transform.Find("ruins_"+id).GetComponent<MeshCollider>();float x=id==57?-10:-7;Check(col.sharedMesh==col.GetComponent<MeshFilter>().sharedMesh,"Collider identity");foreach(float y in new[]{4.05f,4.4f,4.7f})foreach(float dx in new[]{-.2f,0,.2f}){Check(!col.Raycast(new Ray(new Vector3(x+dx,y,-2),Vector3.back),out var through,2),"Window occluded");holes++;}foreach(var pos in new[]{new Vector3(x+.7f,4.2f,-2),new Vector3(x,3.6f,-2),new Vector3(x,5.02f,-2)}){Check(col.Raycast(new Ray(pos,Vector3.back),out var hit,2),"Solid frame missing");solid++;}
 foreach(float dx in new[]{-.2f,0,.2f}){var walker=new GameObject("WindowWalker");var cc=walker.AddComponent<CharacterController>();cc.height=1.6f;cc.center=new Vector3(0,.8f,0);cc.radius=.25f;cc.skinWidth=.015f;cc.stepOffset=.25f;walker.transform.position=new Vector3(x+dx,3.03f,-2);Physics.SyncTransforms();for(int k=0;k<40;k++)cc.Move(new Vector3(0,-.025f,-.05f));Check(walker.transform.position.z>-2.6f,"Window crossed");UnityEngine.Object.DestroyImmediate(walker);}
 foreach(int count in new[]{9,225}){var clones=Enumerable.Range(0,count).Select(k=>{var o=UnityEngine.Object.Instantiate(col.gameObject);o.transform.position=new Vector3(100+k*5,0,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared references");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}}
 int jointRays=0;foreach(float x in new[]{-11f,-9f,-8f,-6f})foreach(float dx in new[]{-.003f,0,.003f})for(float y=3.1f;y<5.02f;y+=.12f){Check(Physics.Raycast(new Ray(new Vector3(x+dx,y,-2),Vector3.back),out var joint,1.3f)&&joint.collider.name.StartsWith("ruins_"),"Wall joint gap");jointRays++;}
 Check(!ShaderUtil.ShaderHasError(mat.shader),"Shader error");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"oldMeshes\":56,\"prefabScenePixelDelta\":0,\"otherPartsPixelDelta\":0,\"capsuleBlocked\":6,\"windowVoidRays\":"+holes+",\"solidFrameRays\":"+solid+",\"jointRays\":"+jointRays+",\"shared9And225Offscreen\":true,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
